var s={en:`Staff submit expense requests. Managers approve small amounts; finance approves large ones. Self-approval is prohibited.`,ua:`Працівники створюють заявки на витрати. Менеджери погоджують малі суми, фінансисти — великі. Самозатвердження заборонене.`};var n={en:[`Add approval states, thresholds and decision history.`,`Define segregation of duties and delegated approval.`,`Connect approved requests to external procurement integration.`],ua:[`Додай стани погодження, ліміти й історію рішень.`,`Визнач розподіл повноважень і делегування.`,`З’єднай схвалені заявки із закупівельною інтеграцією.`]};var r=[{en:`Requesters cannot approve their own requests.`,ua:`Заявники не затверджують власні заявки.`},{en:`Unapproved requests cannot trigger purchases.`,ua:`Несхвалені заявки не запускають закупівлі.`}];var t={scenario:s,tasks:n,checks:r};export{r as checks,t as default,s as scenario,n as tasks};